export function getSolendInitObligationInstruction<
  TAccountFeePayer extends InstructionSignerInput,
  TAccountBank extends InstructionAccountInput,
  TAccountSignerTokenAccount extends InstructionAccountInput,
  TAccountLiquidityVaultAuthority extends InstructionAccountInput,
  TAccountLiquidityVault extends InstructionAccountInput,
  TAccountIntegrationAcc2 extends InstructionAccountInput,
  TAccountLendingMarket extends InstructionAccountInput,
  TAccountLendingMarketAuthority extends InstructionAccountInput,
  TAccountIntegrationAcc1 extends InstructionAccountInput,
  TAccountMint extends InstructionAccountInput,
  TAccountReserveLiquiditySupply extends InstructionAccountInput,
  TAccountReserveCollateralMint extends InstructionAccountInput,
  TAccountReserveCollateralSupply extends InstructionAccountInput,
  TAccountUserCollateral extends InstructionAccountInput,
  TAccountPythPrice extends InstructionAccountInput,
  TAccountSwitchboardFeed extends InstructionAccountInput,
  TAccountSolendProgram extends InstructionAccountInput,
  TAccountTokenProgram extends InstructionAccountInput,
  TAccountRent extends InstructionAccountInput,
  TAccountSystemProgram extends InstructionAccountInput,
  TProgramAddress extends Address = typeof MARGINFI_PROGRAM_ADDRESS,
>(
  input: SolendInitObligationInput<
    TAccountFeePayer,
    TAccountBank,
    TAccountSignerTokenAccount,
    TAccountLiquidityVaultAuthority,
    TAccountLiquidityVault,
    TAccountIntegrationAcc2,
    TAccountLendingMarket,
    TAccountLendingMarketAuthority,
    TAccountIntegrationAcc1,
    TAccountMint,
    TAccountReserveLiquiditySupply,
    TAccountReserveCollateralMint,
    TAccountReserveCollateralSupply,
    TAccountUserCollateral,
    TAccountPythPrice,
    TAccountSwitchboardFeed,
    TAccountSolendProgram,
    TAccountTokenProgram,
    TAccountRent,
    TAccountSystemProgram
  >,
  config?: { programAddress?: TProgramAddress }
): SolendInitObligationInstruction<
  TProgramAddress,
  ResolvedInstructionAccountMeta<
    TAccountFeePayer,
    InstructionAccountInputAddress<TAccountFeePayer>
  >,
  ResolvedInstructionAccountMeta<TAccountBank, InstructionAccountInputAddress<TAccountBank>>,
  ResolvedInstructionAccountMeta<
    TAccountSignerTokenAccount,
    InstructionAccountInputAddress<TAccountSignerTokenAccount>
  >,
  ResolvedInstructionAccountMeta<
    TAccountLiquidityVaultAuthority,
    InstructionAccountInputAddress<TAccountLiquidityVaultAuthority>
  >,
  ResolvedInstructionAccountMeta<
    TAccountLiquidityVault,
    InstructionAccountInputAddress<TAccountLiquidityVault>
  >,
  ResolvedInstructionAccountMeta<
    TAccountIntegrationAcc2,
    InstructionAccountInputAddress<TAccountIntegrationAcc2>
  >,
  ResolvedInstructionAccountMeta<
    TAccountLendingMarket,
    InstructionAccountInputAddress<TAccountLendingMarket>
  >,
  ResolvedInstructionAccountMeta<
    TAccountLendingMarketAuthority,
    InstructionAccountInputAddress<TAccountLendingMarketAuthority>
  >,
  ResolvedInstructionAccountMeta<
    TAccountIntegrationAcc1,
    InstructionAccountInputAddress<TAccountIntegrationAcc1>
  >,
  ResolvedInstructionAccountMeta<TAccountMint, InstructionAccountInputAddress<TAccountMint>>,
  ResolvedInstructionAccountMeta<
    TAccountReserveLiquiditySupply,
    InstructionAccountInputAddress<TAccountReserveLiquiditySupply>
  >,
  ResolvedInstructionAccountMeta<
    TAccountReserveCollateralMint,
    InstructionAccountInputAddress<TAccountReserveCollateralMint>
  >,
  ResolvedInstructionAccountMeta<
    TAccountReserveCollateralSupply,
    InstructionAccountInputAddress<TAccountReserveCollateralSupply>
  >,
  ResolvedInstructionAccountMeta<
    TAccountUserCollateral,
    InstructionAccountInputAddress<TAccountUserCollateral>
  >,
  ResolvedInstructionAccountMeta<
    TAccountPythPrice,
    InstructionAccountInputAddress<TAccountPythPrice>
  >,
  ResolvedInstructionAccountMeta<
    TAccountSwitchboardFeed,
    InstructionAccountInputAddress<TAccountSwitchboardFeed>
  >,
  ResolvedInstructionAccountMeta<
    TAccountSolendProgram,
    InstructionAccountInputAddress<TAccountSolendProgram>
  >,
  ResolvedInstructionAccountMeta<
    TAccountTokenProgram,
    InstructionAccountInputAddress<TAccountTokenProgram>
  >,
  ResolvedInstructionAccountMeta<TAccountRent, InstructionAccountInputAddress<TAccountRent>>,
  ResolvedInstructionAccountMeta<
    TAccountSystemProgram,
    InstructionAccountInputAddress<TAccountSystemProgram>
  >
> {
  // Program address.
  const programAddress = config?.programAddress ?? MARGINFI_PROGRAM_ADDRESS;

  // Account meta helper.
  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");

  // Original accounts.
  const originalAccounts = {
    feePayer: { value: input.feePayer ?? null, isSigner: true, isWritable: true },
    bank: { value: input.bank ?? null, isSigner: false, isWritable: false },
    signerTokenAccount: {
      value: input.signerTokenAccount ?? null,
      isSigner: false,
      isWritable: true,
    },
    liquidityVaultAuthority: {
      value: input.liquidityVaultAuthority ?? null,
      isSigner: false,
      isWritable: false,
    },
    liquidityVault: { value: input.liquidityVault ?? null, isSigner: false, isWritable: true },
    integrationAcc2: { value: input.integrationAcc2 ?? null, isSigner: false, isWritable: true },
    lendingMarket: { value: input.lendingMarket ?? null, isSigner: false, isWritable: false },
    lendingMarketAuthority: {
      value: input.lendingMarketAuthority ?? null,
      isSigner: false,
      isWritable: false,
    },
    integrationAcc1: { value: input.integrationAcc1 ?? null, isSigner: false, isWritable: true },
    mint: { value: input.mint ?? null, isSigner: false, isWritable: true },
    reserveLiquiditySupply: {
      value: input.reserveLiquiditySupply ?? null,
      isSigner: false,
      isWritable: true,
    },
    reserveCollateralMint: {
      value: input.reserveCollateralMint ?? null,
      isSigner: false,
      isWritable: true,
    },
    reserveCollateralSupply: {
      value: input.reserveCollateralSupply ?? null,
      isSigner: false,
      isWritable: true,
    },
    userCollateral: { value: input.userCollateral ?? null, isSigner: false, isWritable: true },
    pythPrice: { value: input.pythPrice ?? null, isSigner: false, isWritable: false },
    switchboardFeed: { value: input.switchboardFeed ?? null, isSigner: false, isWritable: false },
    solendProgram: { value: input.solendProgram ?? null, isSigner: false, isWritable: false },
    tokenProgram: { value: input.tokenProgram ?? null, isSigner: false, isWritable: false },
    rent: { value: input.rent ?? null, isSigner: false, isWritable: false },
    systemProgram: { value: input.systemProgram ?? null, isSigner: false, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedInstructionAccount
  >;

  // Original args.
  const args = { ...input };

  // Resolve default values.
  if (!accounts.solendProgram.value) {
    accounts.solendProgram.value =
      "So1endDq2YkqhipRh3WViPa8hdiSpxWy6z3Z6tMCpAo" as Address<"So1endDq2YkqhipRh3WViPa8hdiSpxWy6z3Z6tMCpAo">;
  }
  if (!accounts.tokenProgram.value) {
    accounts.tokenProgram.value =
      "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA" as Address<"TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA">;
  }
  if (!accounts.rent.value) {
    accounts.rent.value =
      "SysvarRent111111111111111111111111111111111" as Address<"SysvarRent111111111111111111111111111111111">;
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }

  return Object.freeze({
    accounts: [
      getAccountMeta("feePayer", accounts.feePayer),
      getAccountMeta("bank", accounts.bank),
      getAccountMeta("signerTokenAccount", accounts.signerTokenAccount),
      getAccountMeta("liquidityVaultAuthority", accounts.liquidityVaultAuthority),
      getAccountMeta("liquidityVault", accounts.liquidityVault),
      getAccountMeta("integrationAcc2", accounts.integrationAcc2),
      getAccountMeta("lendingMarket", accounts.lendingMarket),
      getAccountMeta("lendingMarketAuthority", accounts.lendingMarketAuthority),
      getAccountMeta("integrationAcc1", accounts.integrationAcc1),
      getAccountMeta("mint", accounts.mint),
      getAccountMeta("reserveLiquiditySupply", accounts.reserveLiquiditySupply),
      getAccountMeta("reserveCollateralMint", accounts.reserveCollateralMint),
      getAccountMeta("reserveCollateralSupply", accounts.reserveCollateralSupply),
      getAccountMeta("userCollateral", accounts.userCollateral),
      getAccountMeta("pythPrice", accounts.pythPrice),
      getAccountMeta("switchboardFeed", accounts.switchboardFeed),
      getAccountMeta("solendProgram", accounts.solendProgram),
      getAccountMeta("tokenProgram", accounts.tokenProgram),
      getAccountMeta("rent", accounts.rent),
      getAccountMeta("systemProgram", accounts.systemProgram),
    ],
    data: getSolendInitObligationInstructionDataEncoder().encode(
      args as SolendInitObligationInstructionDataArgs
    ),
    programAddress,
  } as SolendInitObligationInstruction<
    TProgramAddress,
    ResolvedInstructionAccountMeta<
      TAccountFeePayer,
      InstructionAccountInputAddress<TAccountFeePayer>
    >,
    ResolvedInstructionAccountMeta<TAccountBank, InstructionAccountInputAddress<TAccountBank>>,
    ResolvedInstructionAccountMeta<
      TAccountSignerTokenAccount,
      InstructionAccountInputAddress<TAccountSignerTokenAccount>
    >,
    ResolvedInstructionAccountMeta<
      TAccountLiquidityVaultAuthority,
      InstructionAccountInputAddress<TAccountLiquidityVaultAuthority>
    >,
    ResolvedInstructionAccountMeta<
      TAccountLiquidityVault,
      InstructionAccountInputAddress<TAccountLiquidityVault>
    >,
    ResolvedInstructionAccountMeta<
      TAccountIntegrationAcc2,
      InstructionAccountInputAddress<TAccountIntegrationAcc2>
    >,
    ResolvedInstructionAccountMeta<
      TAccountLendingMarket,
      InstructionAccountInputAddress<TAccountLendingMarket>
    >,
    ResolvedInstructionAccountMeta<
      TAccountLendingMarketAuthority,
      InstructionAccountInputAddress<TAccountLendingMarketAuthority>
    >,
    ResolvedInstructionAccountMeta<
      TAccountIntegrationAcc1,
      InstructionAccountInputAddress<TAccountIntegrationAcc1>
    >,
    ResolvedInstructionAccountMeta<TAccountMint, InstructionAccountInputAddress<TAccountMint>>,
    ResolvedInstructionAccountMeta<
      TAccountReserveLiquiditySupply,
      InstructionAccountInputAddress<TAccountReserveLiquiditySupply>
    >,
    ResolvedInstructionAccountMeta<
      TAccountReserveCollateralMint,
      InstructionAccountInputAddress<TAccountReserveCollateralMint>
    >,
    ResolvedInstructionAccountMeta<
      TAccountReserveCollateralSupply,
      InstructionAccountInputAddress<TAccountReserveCollateralSupply>
    >,
    ResolvedInstructionAccountMeta<
      TAccountUserCollateral,
      InstructionAccountInputAddress<TAccountUserCollateral>
    >,
    ResolvedInstructionAccountMeta<
      TAccountPythPrice,
      InstructionAccountInputAddress<TAccountPythPrice>
    >,
    ResolvedInstructionAccountMeta<
      TAccountSwitchboardFeed,
      InstructionAccountInputAddress<TAccountSwitchboardFeed>
    >,
    ResolvedInstructionAccountMeta<
      TAccountSolendProgram,
      InstructionAccountInputAddress<TAccountSolendProgram>
    >,
    ResolvedInstructionAccountMeta<
      TAccountTokenProgram,
      InstructionAccountInputAddress<TAccountTokenProgram>
    >,
    ResolvedInstructionAccountMeta<TAccountRent, InstructionAccountInputAddress<TAccountRent>>,
    ResolvedInstructionAccountMeta<
      TAccountSystemProgram,
      InstructionAccountInputAddress<TAccountSystemProgram>
    >
  >);
}

export type ParsedSolendInitObligationInstruction<
  TProgram extends string = typeof MARGINFI_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /**
     * Pays to init the obligation and pays a nominal amount to ensure the obligation has a
     * non-zero balance.
     */
    feePayer: TAccountMetas[0];
    bank: TAccountMetas[1];
    /**
     * The fee payer must provide a nominal amount of bank tokens so the obligation is not empty.
     * This amount is irrecoverable and will prevent the obligation from ever being closed.
     */
    signerTokenAccount: TAccountMetas[2];
    /** The liquidity vault authority (PDA that will own the Solend obligation) */
    liquidityVaultAuthority: TAccountMetas[3];
    /** Used as an intermediary to deposit a nominal amount of token into the obligation. */
    liquidityVault: TAccountMetas[4];
    integrationAcc2: TAccountMetas[5];
    lendingMarket: TAccountMetas[6];
    /** Derived from the lending market */
    lendingMarketAuthority: TAccountMetas[7];
    integrationAcc1: TAccountMetas[8];
    /** Bank's liquidity token mint (e.g., USDC) */
    mint: TAccountMetas[9];
    reserveLiquiditySupply: TAccountMetas[10];
    /** The reserve's mint for cTokens */
    reserveCollateralMint: TAccountMetas[11];
    /** The reserve's collateral supply account (where cTokens are stored) */
    reserveCollateralSupply: TAccountMetas[12];
    /**
     * The user's destination for cTokens (collateral). This is a temporary account owned by
     * liquidity_vault_authority that will hold cTokens between deposit and obligation update.
     */
    userCollateral: TAccountMetas[13];
    /** Oracle accounts - required by Solend even if not actively used */
    pythPrice: TAccountMetas[14];
    switchboardFeed: TAccountMetas[15];
    solendProgram: TAccountMetas[16];
    tokenProgram: TAccountMetas[17];
    rent: TAccountMetas[18];
    systemProgram: TAccountMetas[19];
  };
  data: SolendInitObligationInstructionData;
};

export function parseSolendInitObligationInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedSolendInitObligationInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 20) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 20,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      feePayer: getNextAccount(),
      bank: getNextAccount(),
      signerTokenAccount: getNextAccount(),
      liquidityVaultAuthority: getNextAccount(),
      liquidityVault: getNextAccount(),
      integrationAcc2: getNextAccount(),
      lendingMarket: getNextAccount(),
      lendingMarketAuthority: getNextAccount(),
      integrationAcc1: getNextAccount(),
      mint: getNextAccount(),
      reserveLiquiditySupply: getNextAccount(),
      reserveCollateralMint: getNextAccount(),
      reserveCollateralSupply: getNextAccount(),
      userCollateral: getNextAccount(),
      pythPrice: getNextAccount(),
      switchboardFeed: getNextAccount(),
      solendProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      rent: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSolendInitObligationInstructionDataDecoder().decode(instruction.data),
  };
}
